    const r=h.size/2;
    let pts=''; for(let i=0;i<6;i++){ const a=(Math.PI/3)*i - Math.PI/6; pts+=`${r+r*Math.cos(a)},${r+r*Math.sin(a)} `;}
    wrap.innerHTML=`<svg width="${h.size}" height="${h.size}" viewBox="0 0 ${h.size} ${h.size}" style="opacity:0.18"><polygon points="${pts}" fill="none" stroke="${h.color}" stroke-width="1.5"/></svg>`;
