  // --- Reveal ---
  const revealEls=document.querySelectorAll('.reveal');
  if(typeof IntersectionObserver!=='undefined'){
    const obs=new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting) e.target.classList.add('visible');});},{threshold:0.1});
    revealEls.forEach(el=>obs.observe(el));
  } else {
    revealEls.forEach(el=>el.classList.add('visible'));
  }

  // --- Counters ---
  const counters=document.querySelectorAll('.counter');
  if(typeof IntersectionObserver!=='undefined'){
    const counterObs=new IntersectionObserver((entries)=>{
      entries.forEach(entry=>{
        if(entry.isIntersecting){
          const el=entry.target;
          const target=parseInt(el.dataset.target);
          const suffix=el.dataset.suffix||'';
          let start=null;
          const dur=1400;
          function tick(now){
            if(!start) start=now;
            const p=Math.min((now-start)/dur,1);
            const ease=1-Math.pow(1-p,3);
            el.textContent=Math.round(ease*target)+suffix;
            if(p<1) requestAnimationFrame(tick);
          }
          requestAnimationFrame(tick);
          counterObs.unobserve(el);
        }
      });
    },{threshold:0.5});
    counters.forEach(c=>counterObs.observe(c));
  } else {
    counters.forEach(c=>{ const target=parseInt(c.dataset.target); const suffix=c.dataset.suffix||''; c.textContent=target+suffix; });
  }

  // --- Countdown (до пятницы 18:30) ---
  function updateCountdown(){
    const now=new Date();
    const next=new Date(now);
    next.setHours(18,30,0,0);
    next.setMilliseconds(0);
    const day=now.getDay();
    const daysUntil=(5-day+7)%7;
    next.setDate(now.getDate()+daysUntil);
    if(next <= now) next.setDate(next.getDate()+7);
    const diff=Math.max(0,next.getTime()-now.getTime());
    const d=Math.floor(diff/86400000), h=Math.floor((diff%86400000)/3600000), m=Math.floor((diff%3600000)/60000), s=Math.floor((diff%60000)/1000);
    const elD=document.getElementById('cd-d'); if(elD) elD.textContent=String(d).padStart(2,'0');
    const elH=document.getElementById('cd-h'); if(elH) elH.textContent=String(h).padStart(2,'0');
    const elM=document.getElementById('cd-m'); if(elM) elM.textContent=String(m).padStart(2,'0');
    const elS=document.getElementById('cd-s'); if(elS) elS.textContent=String(s).padStart(2,'0');
  }
  updateCountdown(); setInterval(updateCountdown,1000);

